-- Harnwell pilot schedule (Phase C) — recurring weekly assignments from the
-- "Summer Final" sheet (docs/staggered-launch/harnwell-summer-final.csv), parsed
-- exactly (not OCR) and hours-reconciled against the legend (all 9 workers match:
-- Eleni 23, Abraham 24, Drew 24, Valeria 23, Aaron 23, Lealem 24, Ornella 24.5,
-- Andrew C. 23, Purity 30.5; OPEN 7.5; total 226.5). Regenerate with
-- /tmp/gen_assign.py; verify with docs/staggered-launch/verify-harnwell-hours.py.
--
-- Fills the ALREADY-GENERATED vacant Harnwell blocks (the operating config produces
-- single-AM/double-PM weekday + double weekend, matching the sheet) with the fixed
-- weekly pattern keyed on (NY weekday, time-of-day, seat), so the same pattern applies
-- to every week (the recurring-publish semantics). OPEN seats stay vacant/claimable.
-- Only the 9 Harnwell-home desk workers are assigned, so the Harnwell training
-- invariant holds. Idempotent-ish: re-running only touches rows still 'vacant'.
--
BEGIN;
CREATE TEMP TABLE _hw_map (dow int, tod time, seat int, user_id uuid) ON COMMIT DROP;

WITH ranked AS (
  SELECT a.assignment_id, a.block_id,
         EXTRACT(isodow FROM (b.block_start_at AT TIME ZONE 'America/New_York'))::int AS dow,
         (b.block_start_at AT TIME ZONE 'America/New_York')::time AS tod,
         row_number() OVER (PARTITION BY a.block_id ORDER BY a.assignment_id) AS seat_idx
  FROM shift_block_assignments a
  JOIN shift_blocks b ON b.block_id=a.block_id
  WHERE b.house_id='harnwell' AND b.voided_at IS NULL AND a.status='vacant'
)
UPDATE shift_block_assignments t
SET user_id=m.user_id, status='scheduled', vacancy_origin='none'
FROM ranked r
JOIN _hw_map m ON m.dow=r.dow AND m.tod=r.tod AND m.seat=r.seat_idx
WHERE t.assignment_id=r.assignment_id;
COMMIT;
